   {
      internal Core core;
      internal double[] ShadowVeryShortPeriodTotal = [];
      internal double[] EqualPeriodTotal = [];
      internal double lag1_inOpen;
      internal double lag2_inOpen;
      internal double lag1_inHigh;
      internal double lag2_inHigh;
      internal double lag1_inLow;
      internal double lag2_inLow;
      internal double lag1_inClose;
      internal double lag2_inClose;
      internal int ringPos_EqualTrailingIdx;
      internal int ringCap_EqualTrailingIdx;
      internal int ringLag_EqualTrailingIdx;
      internal double[] ring_EqualTrailingIdx_derived = [];
      internal int ringPos_ShadowVeryShortTrailingIdx;
      internal int ringCap_ShadowVeryShortTrailingIdx;
      internal int ringLag_ShadowVeryShortTrailingIdx;
      internal double[] ring_ShadowVeryShortTrailingIdx_derived = [];
      internal int cs_Equal_rangeType;
      internal int cs_Equal_avgPeriod;
      internal double cs_Equal_factor;
      internal int cs_ShadowVeryShort_rangeType;
      internal int cs_ShadowVeryShort_avgPeriod;
      internal double cs_ShadowVeryShort_factor;
      internal int cur_outInteger;
      internal int outRangeBegIdx;
      internal int outRangeCount;

      internal Cdlidentical3crowsStream( Core core ) { this.core = core; }

      /// <summary>The bars this stream has an output for, in the input series' coordinates:
      /// <c>[BegIdx, BegIdx + Count)</c>.</summary>
      /// <remarks>
      /// <para>It is what <c>Core.Cdlidentical3crows</c> reports over the same bars: the
      /// opener sets it to <c>(lookback, historyLen - lookback)</c>, every
      /// <c>Update</c> adds one to the count — a non-finite bar is rejected but
      /// still counted, because the bar happened — <c>Peek</c> leaves it alone, and
      /// <c>Clone</c> carries it verbatim. A plain <c>Open</c> hands back only the
      /// last value, a subset of this range, because the caller chose not to take
      /// the fill.</para>
      /// </remarks>
